import {api,auth,saveSession,hasSession,signOut,verifyLink,configuration} from './client.js';
const demo=location.pathname.includes('/uyelik-onizleme/');
const app=document.getElementById('portal');
const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang='tr';try{lang=localStorage.getItem('turkishMateLanguage')==='en'?'en':'tr';}catch{}
const t=(tr,en)=>lang==='tr'?tr:en;
let catalog=window.AkinDemoCatalog,profile=null,role='student',progress=[],attempts=[],students=[],studentProgress=[],requests=[],slots=[],mode='login',view='learning',level='b1',month=new Date(new Date().getFullYear(),new Date().getMonth(),1),selectedDay=null,selectedSlot=null,quiz=null,feedback=null,notice='',noticeError=false,busy=false,filter={query:'',level:'all',consent:'all'},more=false,offset=0;
const titles={learning:()=>t('Öğrenme yolum','My learning path'),results:()=>t('Sonuçlarım ve geri bildirim','Results and feedback'),lessons:()=>t('Konuşma ve grup dersleri','Speaking and group lessons'),settings:()=>t('Hesap tercihlerim','Account preferences'),students:()=>t('Öğrenci listesi','Student directory'),requests:()=>t('Ders talepleri','Lesson requests'),schedule:()=>t('Ders takvimi','Lesson calendar'),privacy:()=>t('Verilerim ve gizlilik','My data and privacy')};
function kindName(kind){return ({conversation:t('Konuşma dersi','Speaking lesson'),'a1-group':t('A1 grup dersi','A1 group lesson'),'a2-group':t('A2 grup dersi','A2 group lesson'),'b1-group':t('B1 grup dersi','B1 group lesson')})[kind]||kind;}
function date(value,withTime=false){return new Intl.DateTimeFormat(lang==='tr'?'tr-TR':'en-GB',{dateStyle:'medium',...(withTime?{timeStyle:'short'}:{})}).format(new Date(value));}
function time(value){return new Intl.DateTimeFormat(lang==='tr'?'tr-TR':'en-GB',{hour:'2-digit',minute:'2-digit'}).format(new Date(value));}
function summary(l=level,p=progress,a=attempts){const items=catalog.items.filter(i=>i.levels.includes(l)&&i.required!==false),checks=catalog.assessments.filter(i=>i.levels.includes(l)),done=items.filter(i=>p.some(x=>x.content_id===i.id&&x.state==='completed')).length,latest=checks.map(c=>a.filter(x=>x.assessment_id===c.id).sort((a,b)=>b.created_at.localeCompare(a.created_at))[0]).filter(Boolean),total=latest.reduce((n,x)=>n+x.total,0),correct=latest.reduce((n,x)=>n+x.correct,0),score=total?Math.round(correct/total*100):null;return {items,checks,done,percent:items.length?Math.round(done/items.length*100):0,latest,score,ready:items.length>0&&done===items.length&&checks.length>0&&latest.length===checks.length,weak:[...new Set(latest.flatMap(x=>x.mistakes.map(m=>m.tag)))]};}
function fixture(){const b=catalog.items.filter(i=>i.levels.includes('b1'));profile={id:'demo-student',first_name:'Elena',last_name:'Örnek',email:'elena@example.org',level:'b1',timezone:'Europe/Istanbul',marketing_consent:false,created_at:new Date().toISOString()};progress=b.slice(0,5).map(i=>({content_id:i.id,state:'completed',completed_at:new Date().toISOString(),updated_at:new Date().toISOString()}));if(b[5])progress.push({content_id:b[5].id,state:'started',updated_at:new Date().toISOString()});attempts=[];requests=[];slots=[];
 for(let day=new Date().getDate()+1;day<=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();day++){const start=new Date(month.getFullYear(),month.getMonth(),day,9);if(start.getDay()===0||start.getDay()===6)continue;slots.push({id:'demo-slot-'+day,starts_at:start.toISOString(),ends_at:new Date(+start+3600000).toISOString(),kind:day%3===0?'b1-group':'conversation',capacity:day%3===0?6:1});}
 students=[profile,{id:'demo-2',first_name:'Maya',last_name:'Örnek',email:'maya@example.org',level:'a1',marketing_consent:true,created_at:new Date().toISOString()},{id:'demo-3',first_name:'Luca',last_name:'Örnek',email:'luca@example.org',level:'a2',marketing_consent:false,created_at:new Date().toISOString()}];studentProgress=[];
}
function saveDemo(){if(!demo)return;try{localStorage.setItem('akin-demo-v1',JSON.stringify({profile,progress,attempts,requests,slots}));}catch{}}
function loadDemo(){fixture();try{const d=JSON.parse(localStorage.getItem('akin-demo-v1')||'null');if(d?.profile&&Array.isArray(d.progress)&&Array.isArray(d.attempts)&&Array.isArray(d.slots)){profile=d.profile;progress=d.progress;attempts=d.attempts;requests=d.requests||[];slots=d.slots;students[0]=profile;}}catch{}role='student';}
function showNotice(message,error=false){notice=message;noticeError=error;render();}
function toast(message){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),6500);}
function banner(){return demo?`<div class="demo-banner"><div><strong>${t('ORTAK KONTROL · ÖRNEK HESAPLAR','REVIEW PREVIEW · SAMPLE ACCOUNTS')}</strong><small>${t('Örnek veriler bu tarayıcıda tutulur. Gerçek kayıt, e-posta veya rezervasyon yapılmaz.','Sample data stays in this browser. No real accounts, emails or bookings are created.')}</small></div><div class="demo-controls"><button data-action="demo-student">${t('Öğrenci görünümü','Student view')}</button><button data-action="demo-admin">${t('Yönetici görünümü','Admin view')}</button><button data-action="demo-auth">${t('Kayıt / şifre akışı','Signup / password flow')}</button><button data-action="demo-reset">${t('Örneği sıfırla','Reset example')}</button></div></div>`:'';}
function header(){return `<header class="top"><a class="brand" href="../index.html"><b>AA</b>Akın Academy</a><div class="top-actions"><a href="../index.html">${t('Ana sayfa','Home')}</a><div class="lang" aria-label="${t('Dil','Language')}"><button data-action="language" data-lang="tr" class="${lang==='tr'?'active':''}" aria-pressed="${lang==='tr'}">TR</button><button data-action="language" data-lang="en" class="${lang==='en'?'active':''}" aria-pressed="${lang==='en'}">EN</button></div>${profile?`<button class="outline" data-action="logout">${t('Çıkış','Log out')}</button>`:''}</div></header>${banner()}`;}
function noticeHtml(){return notice?`<div class="notice ${noticeError?'error':''}" role="status" aria-live="polite">${E(notice)}</div>`:'';}
function field(name,label,type='text',value='',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${E(value)}" ${extra}></label>`;}
function authPage(){const signup=mode==='signup',reset=mode==='reset',forgot=mode==='forgot';const title=signup?t('Hesabını oluştur','Create your account'):reset?t('Yeni şifreni belirle','Set a new password'):forgot?t('Şifreni yenile','Reset your password'):t('Tekrar hoş geldin','Welcome back');return `<main class="auth-layout"><section class="auth-intro"><div class="eyebrow">${t('TÜRKÇE YOLCULUĞUN','YOUR TURKISH JOURNEY')}</div><h1>${t('Nerede kaldığını bil.<br>Bir sonraki adımını seç.','Know where you left off.<br>Choose your next step.')}</h1><p class="muted">${t('Derslerini, çalışmalarını ve mevcut puanlı etkinlikleri tek bir yerde takip et. A1, A2 ve B1 içeriklerine kendi hızında devam et.','Track your lessons, practice and existing activity results in one place. Continue through A1, A2 and B1 at your own pace.')}</p><div class="panel tint"><b>${t('Kayıt sırasında telefon istemiyoruz.','No phone number at signup.')}</b><p>${t('Telefon yalnızca özel veya grup dersi talebinde istenir. Duyuru e-postaları için ayrıca izin verebilirsin.','A phone number is requested only for a private or group lesson request. You can separately opt in to announcement emails.')}</p></div><img src="../assets/academy/footer.webp" alt="${t('İstanbul Boğazı','The Bosphorus in Istanbul')}"></section><section class="auth-box">${!reset?`<div class="tabs"><button data-action="auth-mode" data-mode="login" class="${mode==='login'?'active':''}">${t('Giriş yap','Log in')}</button><button data-action="auth-mode" data-mode="signup" class="${signup?'active':''}">${t('Üye ol','Sign up')}</button></div>`:''}<h2>${title}</h2>${noticeHtml()}<form id="auth-form" data-form="auth">${signup?`<div class="fields-row">${field('first_name',t('Ad','First name'),'text','', 'required maxlength="80" autocomplete="given-name"')}${field('last_name',t('Soyad','Last name'),'text','','required maxlength="80" autocomplete="family-name"')}</div>`:''}${!reset?field('email',t('E-posta','Email'),'email','','required autocomplete="email"'):''}${!forgot?field('password',t('Şifre · en az 10 karakter','Password · at least 10 characters'),'password','','required minlength="'+(mode==='login'?1:10)+'" maxlength="128" autocomplete="'+(mode==='login'?'current-password':'new-password')+'"'):''}${reset||signup?field('confirm',t('Şifreyi tekrar yaz','Confirm password'),'password','','required minlength="10" autocomplete="new-password"'):''}${signup?`<label class="field"><span>${t('Şu anki seviyen','Your current level')}</span><select name="level" required><option value="a1">A1 · ${t('Başlangıç','Beginner')}</option><option value="a2">A2 · ${t('Temel','Elementary')}</option><option value="b1" selected>B1 · ${t('Orta','Intermediate')}</option></select></label><label class="check"><input type="checkbox" name="marketing_consent"><span>${t('Ders ve grup duyurularını e-posta ile almak istiyorum. İstediğim zaman bu izni kaldırabilirim.','I would like lesson and group announcements by email. I can withdraw this permission at any time.')}</span></label><label class="check"><input type="checkbox" name="data_acknowledgement" required><span>${t('Veri kullanım açıklamasını okudum. 18 yaş altındaysam hesabımı veli veya öğretmenimin rehberliğiyle kullanıyorum.','I have read the data-use information. If I am under 18, I use my account with parent or teacher guidance.')}</span></label><p class="muted"><small>${t('Ad, soyad ve e-posta öğrenci hesabında tutulur.','Your name and email are stored with your student account.')} <button type="button" class="text-button" data-action="privacy">${t('Veri kullanımını oku','Read about data use')}</button></small></p>`:''}<button class="primary wide" type="submit" ${busy?'disabled':''}>${busy?t('Bekle…','Please wait…'):signup?t('Hesabımı oluştur','Create my account'):forgot?t('Şifre yenileme bağlantısı iste','Request password reset link'):reset?t('Yeni şifreyi kaydet','Save new password'):t('Giriş yap','Log in')}</button></form>${mode==='login'?`<button class="text-button" data-action="auth-mode" data-mode="forgot">${t('Şifreni mi unuttun?','Forgot your password?')}</button>`:''}${demo&&forgot?`<button class="text-button" data-action="auth-mode" data-mode="reset">${t('Örnek bağlantıdan şifre yenileme ekranını aç','Open the sample reset-link screen')}</button>`:''}${!demo?`<p class="footer-note">${t('E-posta onayı beklemeden kayıt olup giriş yapabilirsin. Şifre yenilemek için erişebildiğin bir e-posta kullan.','Sign up and log in without email confirmation. Use an email you can access for password recovery.')}</p>`:''}</section></main>`;}
function sidebar(){const userName=E(profile.first_name+' '+profile.last_name);return `<aside class="sidebar"><div class="identity"><span class="avatar">${E(profile.first_name[0]+profile.last_name[0])}</span><div><b>${userName}</b><small>${role==='admin'?t('Yönetici hesabı','Administrator'):t('Öğrenci hesabı','Student account')}</small></div></div>${role==='student'?`<div class="nav-label">${t('Seviyelerim','My levels')}</div><nav class="level-nav" aria-label="${t('Seviyeler','Levels')}">${catalog.levels.map(l=>`<button class="side-button ${view==='learning'&&level===l.id?'active':''}" data-action="level" data-level="${l.id}"><span class="level-id"><b>${l.label}</b><span class="level-name">${E(l[lang])}</span></span><small>${summary(l.id).percent}%</small></button>`).join('')}</nav>`:`<div class="nav-label">${t('Yönetim','Administration')}</div>`}<nav class="other-nav" aria-label="${t('Panel menüsü','Portal menu')}">${(role==='admin'?['students','requests','schedule','privacy']:['results','lessons','settings','privacy']).map(v=>`<button class="side-button ${view===v?'active':''}" data-action="view" data-view="${v}">${titles[v]()}</button>`).join('')}</nav><div class="sidebar-foot">${demo?t('Bu paneldeki isimler ve sonuçlar örnektir.','Names and results in this preview are samples.'):t('İlerlemen hesabına bağlıdır. Başka cihazdan giriş yaparak devam edebilirsin.','Your progress belongs to your account. Log in on another device to continue.')}<br><a href="../seviyeler/b1/" class="text-button">${t('Mevcut kütüphaneyi aç ↗','Open the existing library ↗')}</a></div></aside>`;}
function stats(s){return `<div class="stats"><article class="stat"><small>${t('TAMAMLAMA','COMPLETION')}</small><strong>${s.percent}%</strong><div class="bar"><i style="width:${s.percent}%"></i></div><small>${t(`${s.done} / ${s.items.length} materyal`,`${s.done} / ${s.items.length} materials`)}</small></article><article class="stat"><small>${t('ETKİNLİK BAŞARISI','PRACTICE SCORE')}</small><strong>${s.score===null?'—':s.score+'%'}</strong><small>${s.score===null?t('Henüz etkinlik sonucu yok','No existing activity results yet'):t('Son etkinlik denemelerinden','From latest existing activity results')}</small></article><article class="stat"><small>${t('PUANLI ETKİNLİKLER','SCORED ACTIVITIES')}</small><strong>${s.latest.length}<span style="font-size:17px;color:var(--muted)"> / ${s.checks.length}</span></strong><small>${s.checks.length?t('Mevcut oyunlar ve mini test','Existing games and mini test'):t('Bu seviye için henüz yayımlanmadı','Not published for this level yet')}</small></article></div>`;}
function learning(){const s=summary(),started=s.items.find(i=>progress.some(p=>p.content_id===i.id&&p.state==='started')),next=started||s.items.find(i=>!progress.some(p=>p.content_id===i.id&&p.state==='completed'));return `<div class="intro-row"><div><div class="eyebrow">${t('ÖĞRENME ALANIM','MY LEARNING SPACE')}</div><h1>${t('Merhaba','Hello')}, ${E(profile.first_name)}.</h1><p>${t('Bugün küçük bir adım daha. Kaldığın yerden devam edebilir veya yeni bir konu seçebilirsin.','Take another small step today. Continue where you left off or choose a new topic.')}</p></div><span class="level-pill">${level.toUpperCase()} · ${E(catalog.levels.find(l=>l.id===level)[lang])}</span></div>${stats(s)}${next?`<section class="resume"><div><div class="eyebrow">${started?t('KALDIĞIN YER','WHERE YOU LEFT OFF'):t('SIRADAKİ ADIM','NEXT STEP')}</div><h2>${E(next[lang])}</h2><p>${E(next[lang==='tr'?'descTr':'descEn'])}</p><a class="primary" href="../${E(next.path)}" data-open-id="${next.id}" target="${demo||next.path.endsWith('.pdf')?'_blank':'_self'}" rel="noopener">${t('Çalışmaya devam et ↗','Continue learning ↗')}</a></div><div class="resume-visual"><img src="../assets/academy/galata.webp" alt="" aria-hidden="true"></div></section>`:`<div class="panel tint"><h2>${t('Mevcut materyaller tamamlandı.','Current materials completed.')}</h2><p>${t('Gelişim kontrollerini tamamla ve sonuçlarını incele.','Complete the existing activity results and review your results.')}</p><button class="primary" data-action="view" data-view="results">${t('Sonuçlarımı aç','Open my results')}</button></div>`}<div class="section-heading"><h2>${t('Öğrenme yolun','Your learning path')}</h2><small class="muted">${t('Güncel içerik kataloğu','Current content catalog')}</small></div>${level!=='b1'?`<div class="notice">${t('Bu seviyenin içeriği henüz sınırlı. Yayımlanan yeni materyaller bu listede otomatik görünür; tam seviye değerlendirmesi henüz açık değildir.','Content at this level is currently limited. New published materials appear here automatically; a full level assessment is not available yet.')}</div>`:''}${Object.entries(catalog.topics).map(([id,label])=>{const items=s.items.filter(i=>i.topic===id);if(!items.length)return '';const done=items.filter(i=>progress.some(p=>p.content_id===i.id&&p.state==='completed')).length;return `<details class="topic" open><summary><span class="topic-icon">${id==='converbs'?'Z':id==='past'?'↶':id==='vocabulary'?'Aa':'R'}</span><span><strong>${E(label[lang])}</strong><small>${done} / ${items.length} ${t('tamamlandı','completed')}</small></span></summary>${items.map(i=>{const p=progress.find(p=>p.content_id===i.id),completed=p?.state==='completed';return `<article class="activity"><span class="status-dot ${completed?'done':''}" aria-hidden="true">${completed?'✓':p?'◐':'○'}</span><div><h3>${E(i[lang])}</h3><p>${E(catalog.types[i.types[0]][lang])} · ${t('Kişisel tamamlama kaydı','Self-reported completion')}</p></div><div class="activity-actions"><span class="badge ${completed?'complete':p?'started':'empty'}">${completed?t('Tamamlandı','Completed'):p?t('Başlandı','Started'):t('Sırada','Up next')}</span><a class="outline" target="${demo||i.path.endsWith('.pdf')?'_blank':'_self'}" rel="noopener" href="../${E(i.path)}" data-open-id="${i.id}">${t('Aç ↗','Open ↗')}</a>${!completed?`<button class="outline" data-action="complete" data-id="${i.id}">${t('Tamamladım','Mark completed')}</button>`:''}</div></article>`;}).join('')}<div class="completion-note">${t('Sayfayı açmak tamamlamak sayılmaz. Çalışmanı bitirdiğinde “Tamamladım” seç; bu kayıt başarı puanını değiştirmez.','Opening a page does not complete it. Select “Mark completed” after studying; this record does not change your practice score.')}</div></details>`;}).join('')}${checksHtml(s)}<p class="footer-note">${t('Yeni içerik eklenirse toplam materyal sayısı ve yüzde değişebilir. Önceki tamamlama kayıtların korunur.','New content may change the total and completion percentage. Your earlier completion records are preserved.')}</p>`;}
function checksHtml(s){return `<section class="panel"><h2>${t('Mevcut etkinlik sonuçların','Your existing activity results')}</h2><p class="muted">${t('Ek test yok. Sonuçlar mevcut oyun ve mini testten aktarılır. Tarayıcıdaki alıştırma sonuçlarıdır; resmi sınav doğrulaması değildir. Dedektif oyunlarının tamamlama puanları başarı hesabına katılmaz.','No extra tests. Results come from the existing games and mini test. These are browser practice results, not verified exam results. Detective-game completion points are excluded.')}</p>${s.checks.length?s.checks.map(a=>{const last=s.latest.find(x=>x.assessment_id===a.id);return `<div class="activity"><span class="status-dot">${last?'✓':'○'}</span><div><h3>${E(a[lang])}</h3><p>${last?t(`Son deneme: ${last.correct}/${last.total} · ${date(last.created_at)}`,`Latest attempt: ${last.correct}/${last.total} · ${date(last.created_at)}`):t('Henüz sonuç kaydedilmedi','No result saved yet')}</p></div><a class="outline" href="../${E(a.path)}" data-open-id="${a.content_id}" target="${demo?'_blank':'_self'}" rel="noopener">${t('Etkinliği aç','Open activity')}</a></div>`;}).join(''):`<p>${t('Bu seviyede henüz bağlı puanlı etkinlik yok. İlerlemeni takip edebilirsin.','There are no connected scored activities at this level yet. You can still track completion.')}</p>`}</section>`;}
function results(){const s=summary();return `<div class="eyebrow">${level.toUpperCase()} · ${t('GELİŞİM RAPORU','PROGRESS REPORT')}</div><h1>${titles.results()}</h1>${stats(s)}<section class="panel"><h2>${t('Geri bildirim için gerekenler','Feedback requirements')}</h2><p>${t('Mevcut zorunlu materyalleri ve bu seviyedeki tüm puanlı etkinlikleri tamamla. Tamamlama yüzdesi ve başarı puanı birbirinden farklıdır.','Complete the current required materials and every scored activity for this level. Completion percentage and assessment score are different measures.')}</p><p class="muted">${t('Alıştırma başarısı = her etkinliğin son denemesindeki doğru cevap toplamı ÷ soru toplamı. Sonuçlar tarayıcıdan bildirilir; konuşma, yazma ve tamamlanmış PDF’ler puanlanmaz. %60 altında seviye tekrarı; %60 ve üzerinde isteğe bağlı konuşma pratiği önerilir. Bu bir CEFR sertifikası değildir.','Practice score = correct answers in the latest attempt of each activity ÷ total questions. Results are reported by the browser; speaking, writing and completed PDFs are not scored. Below 60%: repeat the level; 60% or above: optional speaking practice. This is not CEFR certification.')}</p>${s.ready?`<button class="primary" data-action="feedback">${t('Geri bildirimimi hazırla','Prepare my feedback')}</button>`:`<div class="notice">${t('Henüz bütün gereklilikler tamamlanmadı. Eksik materyallere ve mevcut puanlı etkinliklere devam et.','Not all requirements have been completed. Continue with the remaining materials and existing activity results.')}</div>`}${feedback?`<div class="panel tint"><span class="badge">${feedback.source==='ai'?t('Yapay zekâ destekli','AI assisted'):t('Ölçüm kurallarına dayalı · AI kullanılmadı','Based on measured rules · no AI used')}</span><p class="feedback-text" style="margin-top:14px">${E(feedback.text)}</p></div>`:''}${s.ready&&s.score>=60?`<div class="panel tint"><h3>${t('Şimdi Türkçeni konuşarak kullan.','Now use your Turkish in conversation.')}</h3><p>${t('Özel konuşma dersi veya seviyene uygun grup dersi talep edebilirsin. Saatler öğretmenin onayıyla kesinleşir.','Request a private speaking lesson or a group lesson at your level. Times are confirmed by the teacher.')}</p><button class="primary" data-action="view" data-view="lessons">${t('Takvimden ders talep et','Request a lesson from the calendar')}</button></div>`:''}</section>${demo?`<section class="panel"><h3>${t('Kontrol senaryoları · yalnızca örnek','Review scenarios · samples only')}</h3><p class="muted">${t('Tamamlama ve başarı koşullarının iki sonucunu kontrol etmek için örnek verileri değiştirebilirsin. Bunlar gerçek öğrenci sonuçları değildir.','Change the sample records to review both completion and score outcomes.')}</p><button class="outline" data-action="scenario" data-score="high">${t('%60 üzeri örnek','Above 60% example')}</button> <button class="outline" data-action="scenario" data-score="low">${t('%60 altı örnek','Below 60% example')}</button></section>`:''}${checksHtml(s)}`;}
function calendarHtml(){const y=month.getFullYear(),m=month.getMonth(),max=new Date(y,m+1,0).getDate(),start=(month.getDay()+6)%7,available=slots.filter(s=>new Date(s.starts_at).getFullYear()===y&&new Date(s.starts_at).getMonth()===m&&s.available!==false&&Date.parse(s.starts_at)>Date.now());return `<div class="calendar-header"><button class="outline" data-action="month" data-step="-1" aria-label="${t('Önceki ay','Previous month')}">←</button><h3>${new Intl.DateTimeFormat(lang==='tr'?'tr-TR':'en-GB',{month:'long',year:'numeric'}).format(month)}</h3><button class="outline" data-action="month" data-step="1" aria-label="${t('Sonraki ay','Next month')}">→</button></div><div class="calendar">${(lang==='tr'?['Pzt','Sal','Çar','Per','Cum','Cmt','Paz']:['Mon','Tue','Wed','Thu','Fri','Sat','Sun']).map(d=>`<small>${d}</small>`).join('')}${'<span></span>'.repeat(start)}${Array.from({length:max},(_,i)=>{const day=i+1,has=available.some(s=>new Date(s.starts_at).getDate()===day);return `<button class="day ${has?'available':''} ${selectedDay===day?'selected':''}" data-action="day" data-day="${day}" ${!has?'disabled':''} aria-label="${date(new Date(y,m,day))}${has?' · '+t('Ders saati var','Lesson time available'):''}" aria-pressed="${selectedDay===day}">${day}</button>`;}).join('')}</div><p class="footer-note">${t('Saatler cihazının saat diliminde gösterilir','Times are shown in your device timezone')}: ${E(Intl.DateTimeFormat().resolvedOptions().timeZone)}.${demo?' '+t('Mavi günler örnek müsaitliktir.','Blue days are sample availability.'):''}</p>`;}
function lessons(){const selected=slots.filter(s=>new Date(s.starts_at).getFullYear()===month.getFullYear()&&new Date(s.starts_at).getMonth()===month.getMonth()&&new Date(s.starts_at).getDate()===selectedDay&&s.available!==false&&Date.parse(s.starts_at)>Date.now());return `<div class="eyebrow">${t('TÜRKÇEYİ BİRLİKTE KONUŞALIM','LET’S SPEAK TURKISH TOGETHER')}</div><h1>${titles.lessons()}</h1><p class="muted">${t('Konuşma dersi veya A1 / A2 / B1 grup dersi için uygun bir saat seç. Talebin öğretmenin onayını bekler.','Choose an available time for a speaking lesson or A1 / A2 / B1 group lesson. Your request awaits teacher confirmation.')}</p><section class="panel calendar-layout"><div>${calendarHtml()}${!slots.length?`<div class="notice">${t('Henüz yayımlanmış ders saati yok. İletişim bilgileriyle öğretmenine ulaşabilirsin.','No lesson times have been published yet. Contact your teacher using the details below.')}</div>`:''}</div><div><h3>${selectedDay?date(new Date(month.getFullYear(),month.getMonth(),selectedDay)):t('Önce mavi bir gün seç','Select a blue day first')}</h3><div class="slot-list">${selected.map(s=>`<button class="slot-button ${selectedSlot===s.id?'active':''}" data-action="slot" data-id="${E(s.id)}">${time(s.starts_at)} · ${E(kindName(s.kind))}</button>`).join('')}</div><form data-form="lesson">${field('phone',t('Telefon · yalnızca ders talebi için','Phone · only for this lesson request'),'tel','','required minlength="7" maxlength="32" pattern="[+0-9 ()-]{7,32}" autocomplete="tel" placeholder="+90 …"')}<label class="field"><span>${t('Ders hedefin veya notun · isteğe bağlı','Lesson goal or note · optional')}</span><textarea name="note" maxlength="1000"></textarea></label><label class="check"><input type="checkbox" required><span>${t('Bu bir ders talebidir; öğretmen onayından sonra saat kesinleşir. Telefonumun bu talep için kullanılmasını kabul ediyorum.','This is a lesson request; the time is confirmed after teacher approval. I agree to use of my phone number for this request.')}</span></label><button class="primary wide" type="submit" ${!selectedSlot?'disabled':''}>${t('Ders talebimi gönder','Send my lesson request')}</button></form></div></section><div class="panel"><h3>${t('Taleplerim','My requests')}</h3>${requests.length?requests.map(r=>`<div class="request-card"><span class="badge">${statusName(r.status)}</span><p>${E(kindName(slots.find(s=>s.id===r.slot_id)?.kind||'conversation'))} · ${slots.find(s=>s.id===r.slot_id)?date(slots.find(s=>s.id===r.slot_id).starts_at,true):E(r.slot_id)}</p>${['pending','confirmed'].includes(r.status)?`<button class="outline" data-action="cancel-request" data-id="${E(r.id)}">${t('Talebi iptal et','Cancel request')}</button><br>`:''}<small>${r.email_status==='sent'?t('Öğretmene bildirim iletildi.','Teacher notification submitted.'):t('Talep kayıtlı; e-posta bildirimi bekliyor veya gönderilemedi.','Request saved; email notification is pending or failed.')}</small></div>`).join(''):`<p class="muted">${t('Henüz ders talebin yok.','You have no lesson requests yet.')}</p>`}<p><a class="text-button" href="https://wa.me/905319553895" target="_blank" rel="noopener">WhatsApp · +90 531 955 38 95</a><br><a href="mailto:ak.timucin@windowslive.com">ak.timucin@windowslive.com</a></p></div>`;}
function statusName(status){return ({pending:t('Onay bekliyor','Pending confirmation'),confirmed:t('Onaylandı','Confirmed'),declined:t('Uygun bulunmadı','Declined'),cancelled:t('İptal','Cancelled')})[status]||status;}
function settings(){return `<h1>${titles.settings()}</h1><section class="panel"><p><b>${E(profile.first_name+' '+profile.last_name)}</b><br>${E(profile.email)}</p><form data-form="preferences"><label class="field"><span>${t('Çalıştığım seviye','My current level')}</span><select name="level">${catalog.levels.map(l=>`<option value="${l.id}" ${profile.level===l.id?'selected':''}>${l.label} · ${E(l[lang])}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="marketing_consent" ${profile.marketing_consent?'checked':''}><span>${t('Ders ve grup duyurularını e-posta ile almak istiyorum.','I want lesson and group announcements by email.')}</span></label><button class="primary" type="submit">${t('Tercihlerimi kaydet','Save preferences')}</button></form><p class="footer-note">${t('Bu izni kaldırmak şifre yenileme e-postalarını durdurmaz.','Withdrawing this permission does not stop password-reset emails.')}</p></section>`;}
function studentRows(){return students.filter(s=>(filter.level==='all'||s.level===filter.level)&&(filter.consent==='all'||s.marketing_consent===(filter.consent==='yes'))&&[s.first_name,s.last_name,s.email].join(' ').toLocaleLowerCase(lang==='tr'?'tr':'en').includes(filter.query.toLocaleLowerCase(lang==='tr'?'tr':'en'))).sort((a,b)=>a.last_name.localeCompare(b.last_name,lang));}
function studentsHtml(){const rows=studentRows();return `<div class="eyebrow">${t('YÖNETİCİ ALANI','ADMINISTRATOR AREA')}</div><h1>${titles.students()}</h1><p class="muted">${t('Ad, soyad, e-posta ve kayıt bilgilerini seviyeye göre incele. Kayıt formunda telefon bilgisi toplanmaz.','Review names, email addresses and registration details by level. Signup does not collect phone numbers.')}</p><div class="stats"><article class="stat"><small>${t('YÜKLENEN ÖĞRENCİLER','LOADED STUDENTS')}</small><strong>${students.length}</strong><small>${demo?t('Tamamı örnek hesap','All sample accounts'):t('100 kişilik sayfalar halinde','Loaded in pages of 100')}</small></article><article class="stat"><small>${t('BU FİLTREDE','IN THIS FILTER')}</small><strong>${rows.length}</strong><small>A1 · A2 · B1</small></article><article class="stat"><small>${t('DUYURU İZNİ','ANNOUNCEMENT CONSENT')}</small><strong>${students.filter(s=>s.marketing_consent).length}</strong><small>${t('Yalnızca izin verenler','Only opted-in students')}</small></article></div><div class="filters"><input id="student-search" type="search" value="${E(filter.query)}" placeholder="${t('Ad, soyad veya e-posta ara','Search name or email')}" aria-label="${t('Öğrenci ara','Search students')}"><select id="student-level" aria-label="${t('Seviye filtresi','Level filter')}">${['all','a1','a2','b1'].map(l=>`<option value="${l}" ${filter.level===l?'selected':''}>${l==='all'?t('Tüm seviyeler','All levels'):l.toUpperCase()}</option>`).join('')}</select><select id="student-consent" aria-label="${t('Duyuru izni filtresi','Consent filter')}"><option value="all" ${filter.consent==='all'?'selected':''}>${t('Tüm izinler','All permissions')}</option><option value="yes" ${filter.consent==='yes'?'selected':''}>${t('Duyuruya izin verenler','Opted in')}</option><option value="no" ${filter.consent==='no'?'selected':''}>${t('İzin vermeyenler','Not opted in')}</option></select></div><div class="table-wrap"><table><thead><tr>${[t('Öğrenci','Student'),'Email',t('Seviye','Level'),t('İlerleme','Progress'),t('Kayıt','Registered'),t('Duyuru izni','Email consent')].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(s=>{const p=s.id===profile.id?progress:studentProgress.filter(x=>x.user_id===s.id),sum=summary(s.level,p,[]);return `<tr><td><b>${E(s.first_name+' '+s.last_name)}</b><small>${demo?t('Örnek öğrenci','Sample student'):''}</small></td><td>${E(s.email)}</td><td><span class="level-pill">${E(s.level.toUpperCase())}</span></td><td class="student-progress"><b>${sum.percent}%</b><div class="bar"><i style="width:${sum.percent}%"></i></div><small>${sum.done}/${sum.items.length}</small></td><td>${date(s.created_at)}</td><td>${s.marketing_consent?t('İzin var','Opted in'):t('İzin yok','Not opted in')}</td></tr>`;}).join('')||`<tr><td colspan="6">${t('Bu filtrede öğrenci yok.','No students match this filter.')}</td></tr>`}</tbody></table></div>${more?`<button class="outline" data-action="more-students">${t('Sonraki 100 öğrenciyi yükle','Load the next 100 students')}</button>`:''}<section class="panel"><h3>${t('Ders grupları ve duyurular','Lesson groups and announcements')}</h3><p>${t('Seviye ve duyuru iznine göre alıcı listesini hazırlayabilirsin. Bu sürüm toplu e-posta göndermez; abonelikten çıkış ve gönderim servisi kurulmadan yayın kampanyası açılmaz.','Prepare recipients by level and announcement consent. This version does not send bulk email; campaigns require an unsubscribe flow and a connected sending service.')}</p><button class="outline" data-action="export-students">${t('Görünür öğrencileri CSV olarak indir','Download visible students as CSV')}</button> <button class="outline" data-action="export-consent">${t('Yalnızca izinli alıcı listesini indir','Download only opted-in recipients')}</button><p class="footer-note">${t('CSV kişisel bilgi içerir. Yalnızca yetkili kullanım için sakla.','The CSV contains personal information. Keep it for authorized use only.')}</p></section>`;}
function adminRequests(){return `<h1>${titles.requests()}</h1><p class="muted">${t('Talep onayı ve bildirim durumu ayrı gösterilir. E-posta gönderilemese bile kayıt kaybolmaz.','Request approval and notification status are separate. A failed email does not lose the request.')}</p>${requests.map(r=>{const s=slots.find(s=>s.id===r.slot_id),p=students.find(p=>p.id===r.user_id);return `<article class="panel"><span class="badge">${statusName(r.status)}</span><h3 style="margin-top:12px">${E(p?p.first_name+' '+p.last_name:r.user_id)}</h3><p>${E(p?.email||'')}<br>${E(r.phone)}<br>${s?date(s.starts_at,true)+' · '+E(kindName(s.kind)):E(r.slot_id)}</p><p>${E(r.note)}</p><p class="muted">${t('Öğretmene e-posta bildirimi','Teacher email notification')}: ${E(r.email_status)}</p>${r.status==='pending'?`<button class="primary" data-action="request-status" data-id="${E(r.id)}" data-status="confirmed">${t('Onayla','Confirm')}</button> <button class="outline" data-action="request-status" data-id="${E(r.id)}" data-status="declined">${t('Uygun değil','Decline')}</button>`:''}${r.email_status!=='sent'?` <button class="outline" data-action="retry-email" data-id="${E(r.id)}">${t('Bildirimi tekrar dene','Retry notification')}</button>`:''}<p class="footer-note">${t('Onay panelde görünür. Öğrenciye ayrıca e-posta gönderimi bu sürümde yok; öğrencinle iletişim kur.','Confirmation appears in the portal. This version does not email the student on approval; contact your student.')}</p></article>`;}).join('')||`<div class="panel">${t('Henüz talep yok.','No requests yet.')}</div>`}`;}
function schedule(){return `<h1>${titles.schedule()}</h1><p class="muted">${t('Öğrencilerin talep edebileceği gerçek saatleri sen yayımlarsın. Grup kapasitesi aynı saat için talep sınırını belirler.','You publish the real times students can request. Group capacity limits requests for each slot.')}</p><div class="split"><form class="panel" data-form="slot"><h3>${t('Yeni müsaitlik ekle','Add availability')}</h3>${field('starts_at',t('Başlangıç · cihaz saat dilimi','Start · device timezone'),'datetime-local','','required')}${field('ends_at',t('Bitiş','End'),'datetime-local','','required')}<label class="field"><span>${t('Ders türü','Lesson type')}</span><select name="kind">${['conversation','a1-group','a2-group','b1-group'].map(k=>`<option value="${k}">${kindName(k)}</option>`).join('')}</select></label>${field('capacity',t('Kontenjan · 1–12','Capacity · 1–12'),'number','1','required min="1" max="12"')}<button class="primary" type="submit">${t('Takvime ekle','Add to calendar')}</button></form><section class="panel"><h3>${t('Yayımlanan saatler','Published slots')}</h3>${slots.map(s=>`<div class="request-card"><b>${date(s.starts_at,true)}</b><p>${E(kindName(s.kind))} · ${s.capacity} ${t('kişilik','places')} · ${time(s.ends_at)}</p></div>`).join('')||`<p class="muted">${t('Henüz saat eklenmedi.','No times added yet.')}</p>`}</section></div>`;}
function privacy(){return `<section class="panel privacy"><h1>${titles.privacy()}</h1><p>${t('Öğrenci hesabı için ad, soyad, e-posta, seviye ve duyuru izni tutulur. Kayıt sırasında telefon alınmaz.','Your student account stores first name, last name, email, level and announcement consent. Signup does not collect a phone number.')}</p><ul><li>${t('Telefon yalnızca ders talebinde, o taleple birlikte saklanır.','Your phone is stored only with a lesson request.')}</li><li>${t('Tamamlama kayıtları ve etkinlik sonuçları gelişim takibi içindir. Tarayıcıdan kaydedilen puanlar resmi sınav sonucu değildir.','Completion records and browser-reported practice results are used to track progress. They are not verified exam results.')}</li><li>${t('Yönetici öğrenci listelerini ve ders taleplerini görebilir. Diğer öğrenciler verilerini göremez.','The administrator can see student lists and lesson requests. Other students cannot see your data.')}</li><li>${t('AI özelliği bağlandığında yalnızca ölçüm özeti ve konu etiketleri gönderilir; ad, e-posta ve telefon gönderilmez.','When AI is connected, only assessment summaries and topic tags are sent; not your name, email or phone.')}</li><li>${t('Duyuru iznini hesap tercihlerinden kaldırabilirsin. Veri düzeltme veya hesap silme için öğretmenine ulaş.','Withdraw announcement consent in account preferences. Contact your teacher to correct data or delete your account.')}</li></ul><p><a href="mailto:ak.timucin@windowslive.com">ak.timucin@windowslive.com</a></p><p class="footer-note">${t('Yayın öncesinde işletmenin gerçek veri saklama süreleri, hizmet sağlayıcı bilgileri ve çocuklar için veli süreci ayrıca tamamlanmalıdır.','Before launch, finalize actual retention periods, service-provider information and the parent process for children.')}</p><button class="outline" data-action="privacy-back">${t('Geri dön','Go back')}</button></section>`;}
let privacyAuth=false;
function render(){document.documentElement.lang=lang;document.title='Akın Academy · '+(profile&&titles[view]?titles[view]():t('Hesabım','My account'));app.innerHTML=header()+(!profile?(privacyAuth?`<main class="content" style="max-width:900px;margin:auto">${privacy()}</main>`:authPage()):`<div class="frame">${sidebar()}<main class="content">${noticeHtml()}${({learning,results,lessons,settings,students:studentsHtml,requests:adminRequests,schedule,privacy})[view]()}</main></div>`);}
async function refresh(){if(demo){saveDemo();return;}const a=await api('activity');progress=a.progress;attempts=a.attempts;}
async function changeView(next){quiz=null;notice='';feedback=null;view=next;if(!demo){if(next==='students'){const b=await api('admin/students');students=b.students;studentProgress=b.progress;more=b.hasMore;offset=students.length;}if(next==='lessons'){const [a,b]=await Promise.all([api('slots'),api('requests')]);slots=[...(b.slots||[]).filter(s=>!a.slots.some(x=>x.id===s.id)).map(s=>({...s,available:false})),...a.slots];requests=b.requests;}if(next==='requests'||next==='schedule'){const b=await api('admin/requests');requests=b.requests;slots=b.slots;}}render();}
async function mark(id,state){if(demo){const old=progress.find(p=>p.content_id===id);if(old?.state==='completed')return;if(old){old.state=state;old.updated_at=new Date().toISOString();}else progress.push({content_id:id,state,updated_at:new Date().toISOString()});saveDemo();}else{await api('progress',{content_id:id,state});await refresh();}feedback=null;}
app.addEventListener('click',async event=>{const link=event.target.closest('[data-open-id]');if(link){try{await mark(link.dataset.openId,'started');render();}catch(e){toast(e.message);}return;}const b=event.target.closest('[data-action]');if(!b||busy)return;const action=b.dataset.action;
 try{
 if(action==='language'){lang=b.dataset.lang;try{localStorage.setItem('turkishMateLanguage',lang);}catch{}feedback=null;render();}
 else if(action==='auth-mode'){mode=b.dataset.mode;notice='';privacyAuth=false;render();}
 else if(action==='demo-student'){if(!profile)loadDemo();role='student';view='learning';privacyAuth=false;quiz=null;notice='';render();}
 else if(action==='demo-admin'){if(!profile)loadDemo();role='admin';view='students';quiz=null;notice='';render();}
 else if(action==='demo-auth'){profile=null;mode='signup';privacyAuth=false;notice='';render();}
 else if(action==='demo-reset'){fixture();role='student';view='learning';level='b1';quiz=null;feedback=null;notice='';month=new Date(new Date().getFullYear(),new Date().getMonth(),1);selectedDay=null;selectedSlot=null;saveDemo();render();}
 else if(action==='logout'){if(!demo)await signOut();profile=null;mode='login';notice='';render();}
 else if(action==='level'){level=b.dataset.level;view='learning';quiz=null;feedback=null;notice='';render();}
 else if(action==='view'){await changeView(b.dataset.view);}
 else if(action==='complete'){await mark(b.dataset.id,'completed');render();toast(t('Tamamlama kaydı güncellendi.','Completion record updated.'));}
 else if(action==='feedback'){const s=summary();if(!s.ready)throw Error(t('Önce tüm gereklilikleri tamamla.','Complete all requirements first.'));if(demo)feedback={source:'rules',text:t(`Örnek rapor: ${level.toUpperCase()} seviyesinde başarı %${s.score}. ${s.score<60?'Seviyeyi tekrar etmeni öneriyoruz.':'Konuşma pratiğiyle devam edebilirsin.'} ${s.weak.length?'Odaklan: '+s.weak.join(', ')+'.':'Kaydedilen etkinliklerde yanlış yok.'} Konuşma ve telaffuz ölçülmedi. Gerçek AI servisine istek gönderilmedi.`,`Sample report: ${s.score}% in ${level.toUpperCase()}. ${s.score<60?'We recommend repeating this level.':'You can continue with speaking practice.'} ${s.weak.length?'Focus: '+s.weak.join(', ')+'.':'No errors in the latest activities.'} Speaking and pronunciation were not assessed. No real AI request was sent.`)};else feedback=await api('feedback',{level,language:lang});render();}
 else if(action==='scenario'){const s=summary();s.items.forEach(i=>{let p=progress.find(p=>p.content_id===i.id);if(p)p.state='completed';else progress.push({content_id:i.id,state:'completed',updated_at:new Date().toISOString()});});attempts=attempts.filter(a=>!s.checks.some(c=>c.id===a.assessment_id));s.checks.forEach(c=>attempts.push({assessment_id:c.id,correct:Math.floor(c.total*(b.dataset.score==='high'?.8:.5)),total:c.total,mistakes:[{tag:c[lang]}],created_at:new Date().toISOString()}));saveDemo();feedback=null;render();}
 else if(action==='month'){month=new Date(month.getFullYear(),month.getMonth()+Number(b.dataset.step),1);selectedDay=null;selectedSlot=null;render();}
 else if(action==='day'){selectedDay=Number(b.dataset.day);selectedSlot=null;render();}
 else if(action==='slot'){selectedSlot=b.dataset.id;render();}
 else if(action==='cancel-request'){if(demo){const r=requests.find(r=>r.id===b.dataset.id);r.status='cancelled';saveDemo();}else await api('cancel-request',{id:b.dataset.id});await changeView('lessons');}
 else if(action==='request-status'){const r=requests.find(r=>r.id===b.dataset.id);if(demo)r.status=b.dataset.status;else await api('admin/request',{id:b.dataset.id,status:b.dataset.status});saveDemo();await changeView('requests');}
 else if(action==='retry-email'){if(demo)toast(t('Örnekte e-posta gönderilmez.','This preview does not send email.'));else{const r=await api('admin/retry-email',{id:b.dataset.id});toast(r.email_sent?t('Bildirim servise iletildi.','Notification submitted to the mail service.'):t('Bildirim gönderilemedi. Servis ayarlarını kontrol et.','Notification failed. Check service configuration.'));await changeView('requests');}}
 else if(action==='more-students'){const r=await api('admin/students?offset='+offset);students.push(...r.students);studentProgress.push(...r.progress);more=r.hasMore;offset+=r.students.length;render();}
 else if(action==='export-students'||action==='export-consent'){const rows=studentRows().filter(s=>action==='export-students'||s.marketing_consent),cell=x=>'"'+String(x??'').replace(/^(\s*)([=+@-])/,"'$1$2").replace(/"/g,'""')+'"',csv='\ufeff'+[['First name','Last name','Email','Level','Email consent'],...rows.map(s=>[s.first_name,s.last_name,s.email,s.level,s.marketing_consent?'yes':'no'])].map(r=>r.map(cell).join(',')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='akin-students'+(demo?'-SAMPLE':'')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
 else if(action==='privacy'){privacyAuth=true;render();}
 else if(action==='privacy-back'){privacyAuth=false;if(profile)view=role==='admin'?'students':'settings';render();}
 }catch(e){toast(e.message);}
});
app.addEventListener('change',e=>{if(e.target.id==='student-level')filter.level=e.target.value;else if(e.target.id==='student-consent')filter.consent=e.target.value;else return;render();});
app.addEventListener('input',e=>{if(e.target.id!=='student-search')return;const start=e.target.selectionStart;filter.query=e.target.value;render();const input=document.getElementById('student-search');input.focus();input.setSelectionRange(start,start);});
app.addEventListener('submit',async event=>{const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();if(busy)return;if(!form.reportValidity())return;const f=new FormData(form),data=Object.fromEntries(f),kind=form.dataset.form;busy=true;form.querySelector('[type="submit"]').disabled=true;
 try{
 if(kind==='auth'){
  if((mode==='signup'||mode==='reset')&&data.password!==data.confirm)throw Error(t('Şifreler eşleşmiyor.','Passwords do not match.'));
  if(mode==='signup'&&(!data.first_name.trim()||!data.last_name.trim()))throw Error(t('Ad ve soyad gerekli.','First and last names are required.'));
  if(demo){if(mode==='signup'){fixture();profile={...profile,first_name:data.first_name.trim(),last_name:data.last_name.trim(),email:data.email,level:data.level,marketing_consent:!!data.marketing_consent};students[0]=profile;level=data.level;saveDemo();showNotice(t('Örnek kayıt tamamlandı. E-posta gönderilmedi; öğrenci görünümünü açabilirsin.','Sample signup completed. No email was sent; open the student view.'));view='learning';render();}else if(mode==='login'){loadDemo();view='learning';notice='';render();}else if(mode==='forgot')showNotice(t('Örnek: gerçek bir e-posta gönderilmedi. Aşağıdan örnek şifre yenileme ekranını açabilirsin.','Sample only: no email was sent. Open the sample reset screen below.'));else{mode='login';showNotice(t('Örnek şifre yenileme tamamlandı. Şifre kaydedilmedi ve gerçek hesap değiştirilmedi.','Sample password reset completed. No password was stored or real account changed.'));}}
  else if(mode==='signup'){const result=await auth('signup',{email:data.email.trim(),password:data.password,data:{first_name:data.first_name.trim(),last_name:data.last_name.trim(),level:data.level,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,marketing_consent:!!data.marketing_consent}});if(result.access_token){saveSession(result);await startReal();notice=t('Hesabın oluşturuldu. Hoş geldin!','Your account was created. Welcome!');}else{mode='login';showNotice(t('Kayıt için otomatik giriş alınamadı. Giriş yapmayı dene; e-posta onayı ayarını yönetici kontrol etmelidir.','No automatic session was returned. Try logging in; the administrator should check the email confirmation setting.'));}}
  else if(mode==='login'){const s=await auth('token?grant_type=password',{email:data.email,password:data.password});saveSession(s);await startReal();}
  else if(mode==='forgot'){await auth('recover',{email:data.email});showNotice(t('Bu e-posta için uygun bir hesap varsa şifre yenileme bağlantısı gönderilir. Gelen kutunu ve spam klasörünü kontrol et.','If an eligible account exists for this email, a reset link will be sent. Check your inbox and spam folder.'));}
  else if(mode==='reset'){await auth('user',{password:data.password},'PUT',true);await signOut();profile=null;mode='login';showNotice(t('Şifren güncellendi. Yeni şifrenle giriş yap.','Your password was updated. Log in with your new password.'));}
 }
 else if(kind==='preferences'){const d={level:data.level,marketing_consent:!!data.marketing_consent};if(!demo)await api('preferences',d);Object.assign(profile,d);saveDemo();toast(t('Tercihler kaydedildi.','Preferences saved.'));render();}
 else if(kind==='lesson'){if(!/^\+?[0-9 ()-]{7,32}$/.test(data.phone)||(data.phone.match(/\d/g)||[]).length<7||(data.phone.match(/\d/g)||[]).length>15)throw Error(t('Geçerli bir telefon numarası yaz.','Enter a valid phone number.'));if(!selectedSlot)throw Error(t('Bir saat seç.','Choose a time.'));let email_sent=false;if(demo){if(requests.some(r=>r.slot_id===selectedSlot&&['pending','confirmed'].includes(r.status)))throw Error(t('Bu saate zaten bir talebin var.','You already have a request for this slot.'));requests.push({id:'demo-request-'+Date.now(),user_id:profile.id,slot_id:selectedSlot,phone:data.phone,note:data.note,status:'pending',email_status:'pending',created_at:new Date().toISOString()});saveDemo();}else{const r=await api('requests',{slot_id:selectedSlot,phone:data.phone,note:data.note});email_sent=r.email_sent;const all=await api('requests');requests=all.requests;}selectedSlot=null;showNotice(demo?t('Örnek ders talebi kaydedildi. E-posta gönderilmedi.','Sample lesson request saved. No email was sent.'):email_sent?t('Talebin kaydedildi ve öğretmene bildirim servise iletildi. Öğretmen onayından sonra kesinleşir.','Your request was saved and the teacher notification submitted. It is confirmed after teacher approval.'):t('Talebin kaydedildi; e-posta bildirimi gönderilemedi. Öğretmen talebini panelde görebilir.','Your request was saved; email notification failed. Your teacher can see it in the portal.'));}
 else if(kind==='slot'){const s={starts_at:new Date(data.starts_at).toISOString(),ends_at:new Date(data.ends_at).toISOString(),kind:data.kind,capacity:Number(data.capacity)};if(Date.parse(s.starts_at)<=Date.now()||Date.parse(s.ends_at)<=Date.parse(s.starts_at))throw Error(t('Gelecekte ve geçerli bir saat aralığı seç.','Choose a valid future time range.'));if(demo){slots.push({...s,id:'demo-slot-'+Date.now()});saveDemo();}else await api('admin/slots',s);await changeView('schedule');toast(t('Ders saati eklendi.','Lesson slot added.'));}
 }catch(e){showNotice(e.message,true);}finally{busy=false;render();}
});
async function startReal(){const me=await api('me');profile=me.profile;role=me.role;level=profile.level;await refresh();await changeView(role==='admin'?'students':'learning');}
async function init(){if(demo){loadDemo();render();return;}try{const r=await fetch('../assets/learning/catalog.json',{cache:'no-store'});catalog=await r.json();const modeFromLink=await verifyLink();if(modeFromLink==='reset'){mode='reset';profile=null;notice=t('Doğrulama tamamlandı. Yeni şifreni belirle.','Verification completed. Set your new password.');}else if(hasSession())await startReal();else{const c=await configuration();if(!c.configured)notice=t('Bu sürümün üyelik servisi henüz bağlanmadı. Ortak kontrol önizlemesiyle ekranları inceleyebilirsin.','The membership service is not connected yet. Review the screens in the sample preview.');}render();}catch(e){profile=null;notice=e.message;noticeError=true;render();}}
init();

async function syncPublishedCatalog(){if(demo||!profile||busy||quiz||!['learning','results'].includes(view)||document.visibilityState==='hidden')return;try{const response=await fetch('../assets/learning/catalog.json',{cache:'no-store'});if(!response.ok)return;const next=await response.json();if(JSON.stringify(next)!==JSON.stringify(catalog)){catalog=next;feedback=null;notice=t('İçerik kataloğu güncellendi; önceki tamamlama kayıtların korundu.','The content catalog was updated; earlier completions were preserved.');}await refresh();render();}catch{/* Keep the last known catalog and progress during network failures. */}}
if(!demo){window.addEventListener('focus',syncPublishedCatalog);document.addEventListener('visibilitychange',syncPublishedCatalog);setInterval(syncPublishedCatalog,300000);}
